(function(){
'use strict';
const topics=['General','Inquiry process','Rights and safeguards','Committee practice'];
const reasons=['Identifying information','Confidential case details','Abuse or harassment','Spam or misleading content'];
const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=x=>new Date(x).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
let generation=0;
async function api(path,body){const r=await fetch('/api/community/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});let data;try{data=await r.json()}catch{throw Error('Community is temporarily unavailable. Please try again later.')}if(!r.ok)throw Error(data.error||'Please try again later.');return data;}
const safety=`<aside class="community-safety"><strong>Keep the discussion general.</strong><p>Do not post names, phone numbers, email addresses, employer identifiers, case documents or details that could identify anyone. Every question and answer is reviewed before publication. Community answers are personal contributions, not verified legal advice or a complaint-filing service.</p></aside>`;
const consent=`<div class="community-trap" aria-hidden="true"><label>Leave this blank<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="community-consent"><input type="checkbox" name="consent" required><span>I have removed identifying and confidential information and agree to moderator review before publication.</span></label>`;
function report(id,kind){return `<details class="community-report"><summary>Report this ${kind}</summary><form data-community="report" data-id="${escape(id)}" data-kind="${kind}"><label>Reason<select name="reason" required>${reasons.map(x=>`<option>${escape(x)}</option>`).join('')}</select></label><button class="btn btn-light" type="submit">Send report</button><p class="community-feedback" role="status"></p></form></details>`;}
function postMeta(p){return `<p class="community-meta">${escape(p.alias)} · ${escape(date(p.created_at))} · Moderator-approved</p>`;}
function answerMarkup(a){return `<article class="community-answer">${postMeta(a)}<p class="community-body">${escape(a.body)}</p>${report(a.id,'answer')}</article>`;}
function updateSearch(content){const input=content.querySelector('#community-search');if(!input)return;const term=input.value.toLowerCase().trim();let visible=0;for(const el of content.querySelectorAll('[data-question-search]')){el.hidden=!el.dataset.questionSearch.includes(term);if(!el.hidden)visible++;}const empty=content.querySelector('#community-no-results');if(empty)empty.hidden=!term||visible>0;}
function questionForm(){return `<section class="community-compose"><h2>Ask a general question</h2><p>No sign-in, name or phone number is required. A generated alias will appear with an approved post.</p><form data-community="question"><label>Topic<select name="category">${topics.map(x=>`<option>${escape(x)}</option>`).join('')}</select></label><label>Question title (10–160 characters)<input name="title" minlength="10" maxlength="160" required placeholder="Ask a general question about the process"></label><label>Question (20–2,000 characters)<textarea name="body" minlength="20" maxlength="2000" rows="5" required placeholder="Keep it general. Leave out identifying and confidential details."></textarea></label>${consent}<button class="btn btn-dark" type="submit">Submit for review</button><p class="community-feedback" role="status"></p></form></section>`;}
async function render(app,path){
 const current=++generation;
 app.innerHTML=`<section class="app-heading"><div class="wrap"><div><a class="app-back" href="#home">← Back to homepage</a><small>COMMUNITY · NO SIGN-IN</small><h1>Questions shared. Perspectives exchanged.</h1><p>Ask and answer general questions under generated aliases. Your name and contact details are not requested.</p></div><span class="app-mini">Reviewed before publication</span></div></section><div class="app-bg"><div class="wrap workspace community-shell">${safety}<div id="community-content" aria-live="polite"><p>Loading community…</p></div><details class="community-privacy"><summary>How privacy and moderation work</summary><p>No account or public profile is created. Aliases are generated separately for each post, so they do not prove authorship or professional credentials. We do not request names, email addresses or phone numbers. Moderators review submissions and may reject, edit before approval, or hide content that could identify someone.</p><p>This is anonymous to other readers, not a guarantee of untraceability: hosting providers may process IP addresses and other technical logs. A short-lived network fingerprint is held in server memory for submission limits. Do not include real case facts or personal information. Posts approved for publication can be copied by others.</p><p>No direct messages or attachments. Use Report on an approved post to request review or removal. Without an account, you cannot edit a submission yourself. Save its receipt number if you need to refer to it.</p></details></div></div>`;
 const content=document.getElementById('community-content');
 try{
  const config=await api('config');if(current!==generation||!location.hash.startsWith('#community'))return;
  if(!config.enabled){content.innerHTML='<p class="notice warning">The community is not accepting submissions yet. Please return later.</p>';return;}
  const id=path.split('/')[1];
  if(id){
   const data=await api('questions/'+encodeURIComponent(id));if(current!==generation||!location.hash.startsWith('#community'))return;
   const q=data.question;
   content.innerHTML=`<a class="text-link" href="#community">← All questions</a><article class="community-question"><span class="status-pill">${escape(q.category)}</span><h2>${escape(q.title)}</h2>${postMeta(q)}<p class="community-body">${escape(q.body)}</p>${report(q.id,'question')}</article><section class="community-answers"><h2>Community answers</h2><p id="community-answer-count">Showing ${data.answers.length} approved answer(s).</p><div id="community-answer-list">${data.answers.length?data.answers.map(answerMarkup).join(''):'<p>No approved answers yet. You can contribute a general response below.</p>'}</div><button type="button" class="btn btn-light" id="community-answer-more" ${data.answersHasMore?'':'hidden'}>Load more answers</button><p id="community-answer-status" role="status"></p></section><section class="community-compose"><h2>Share a general answer</h2><p>Do not identify people or present an opinion as an official Committee or legal determination.</p><form data-community="answer" data-id="${escape(q.id)}"><label>Your answer (20–2,000 characters)<textarea name="body" minlength="20" maxlength="2000" rows="5" required></textarea></label>${consent}<button class="btn btn-dark" type="submit">Submit answer for review</button><p class="community-feedback" role="status"></p></form></section>`;
   let answerOffset=data.nextAnswerOffset??data.answers.length;const answerIds=new Set(data.answers.map(a=>a.id));
   document.getElementById('community-answer-more').addEventListener('click',async e=>{const button=e.target;button.disabled=true;const status=content.querySelector('#community-answer-status');status.textContent='Loading answers…';try{const next=await api('questions/'+encodeURIComponent(id)+'?answers_offset='+answerOffset);if(current!==generation)return;for(const a of next.answers){if(answerIds.has(a.id))continue;answerIds.add(a.id);content.querySelector('#community-answer-list').insertAdjacentHTML('beforeend',answerMarkup(a));}answerOffset=next.nextAnswerOffset;button.hidden=!next.answersHasMore;content.querySelector('#community-answer-count').textContent='Showing '+answerIds.size+' approved answer(s).';status.textContent=next.answersHasMore?'More answers loaded.':'All approved answers loaded.';}catch(err){status.textContent=err.message}finally{button.disabled=false;}});
  }else{
   const data=await api('questions');if(current!==generation||!location.hash.startsWith('#community'))return;
   content.innerHTML=`<div class="community-toolbar"><div><h2>Approved questions</h2><p>Only moderator-approved questions and answers appear here.</p></div><a href="#community-ask" class="btn btn-gold" data-community-ask>Ask a question</a></div><label class="community-search">Search these questions<input type="search" id="community-search" placeholder="Search titles and topics"></label><div class="community-list">${data.questions.length?data.questions.map(q=>`<article class="community-question" data-question-search="${escape((q.title+' '+q.category).toLowerCase())}"><span class="status-pill">${escape(q.category)}</span><h3><a href="#community/${escape(q.id)}">${escape(q.title)}</a></h3>${postMeta(q)}<p>${escape(q.body.slice(0,220))}${q.body.length>220?'…':''}</p><a class="text-link" href="#community/${escape(q.id)}">Read and answer →</a></article>`).join(''):'<div class="community-empty"><h3>Be the first to ask.</h3><p>No approved questions yet. Submit a general question below to start the conversation.</p></div>'}</div><p id="community-no-results" role="status" hidden>No matching question in the loaded results. Try another phrase or load more questions.</p><div class="community-pagination"><button type="button" class="btn btn-light" id="community-more" ${data.questions.length<20?'hidden':''}>Load more questions</button><p id="community-page-status" role="status"></p></div><div id="community-ask">${questionForm()}</div>`;
   document.getElementById('community-search').addEventListener('input',e=>{updateSearch(content)});
   let offset=20;document.getElementById('community-more').addEventListener('click',async e=>{const button=e.target;button.disabled=true;const status=document.getElementById('community-page-status');try{const next=await api('questions?offset='+offset);if(current!==generation)return;offset+=next.questions.length;const list=content.querySelector('.community-list');for(const q of next.questions){const item=document.createElement('article');item.className='community-question';item.dataset.questionSearch=(q.title+' '+q.category).toLowerCase();item.innerHTML=`<span class="status-pill">${escape(q.category)}</span><h3><a href="#community/${escape(q.id)}">${escape(q.title)}</a></h3>${postMeta(q)}<p>${escape(q.body.slice(0,220))}</p><a href="#community/${escape(q.id)}">Read and answer →</a>`;list.append(item)}updateSearch(content);button.hidden=next.questions.length<20;status.textContent=next.questions.length?'More questions loaded.':'No more approved questions.'}catch(err){status.textContent=err.message}finally{button.disabled=false}});
  }
 }catch(err){if(current===generation)content.innerHTML=`<p class="notice warning">${escape(err.message)}</p><button type="button" class="btn btn-light" data-community-retry>Try again</button> <a href="#community">All questions</a>`;}
}
document.addEventListener('click',e=>{if(e.target.closest('[data-community-retry]')){render(document.getElementById('app'),location.hash.slice(1));return;}const a=e.target.closest('[data-community-ask]');if(a){e.preventDefault();document.getElementById('community-ask')?.scrollIntoView({behavior:'smooth'});document.querySelector('[name="title"]')?.focus({preventScroll:true});}});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!form.dataset.community)return;e.preventDefault();const kind=form.dataset.community,values=new FormData(form),button=form.querySelector('button[type=submit]'),status=form.querySelector('.community-feedback');button.disabled=true;status.textContent='Submitting…';
 const body=Object.fromEntries(values);body.consent=kind==='report'||values.get('consent')==='on';if(kind==='answer')body.question_id=form.dataset.id;if(kind==='report'){body.post_id=form.dataset.id;body.kind=form.dataset.kind;}
 try{const data=await api(kind==='question'?'questions':kind==='answer'?'answers':'reports',body);form.reset();status.textContent=kind==='report'?'Report received for private review.':`Received for moderator review. It is not public yet. Save your receipt: ${data.receipt}`;status.classList.add('success');}catch(err){status.textContent=err.message;status.classList.remove('success');}finally{button.disabled=false;}
});
window.NavigatorCommunity={render};
})();
